from .schema import Lesson


LESSONS = [
Lesson("21-tokenizer", 4, "متن قابل اعتماد", "شناسهٔ ناشناخته و حفظ قرارداد واژگان",
"نشانه‌بند ساده را به جزئی تبدیل کنیم که ذخیره شود، دوباره باز شود و روی متن ندیده رفتار مشخصی داشته باشد.",
"""<p>نشانه‌بند بخش اول برای «ژ» ندیده، خطا می‌داد. حالا باید تصمیم بگیریم با چنین ورودی‌ای چه کنیم. <dfn>Special token (نشانهٔ ویژهٔ قراردادی)</dfn> واحدی است که برای نقش مشخصی به واژگان اضافه می‌کنیم. در پروژه، شناسهٔ صفر همیشه به <code>&lt;|unk|&gt;</code> تعلق دارد.</p>
<p><dfn>Unknown token (نشانهٔ ناشناخته)</dfn> نمایندهٔ چیزی است که در واژگان نیست. نشانه‌بند ما هر کاراکترِ ندیده را به صفر می‌برد و هنگام بازگردانی، آن را با «�» نشان می‌دهد. پس بازگردانی متن ناشناخته بی‌اتلاف نیست. اگر ژ و چ هر دو ندیده باشند، از روی صفر نمی‌توان فهمید کدام‌یک بوده‌اند.</p>
<p>نشانه‌های ویژهٔ رایج دیگر عبارت‌اند از <dfn>Padding یا pad (پرکنندهٔ طول)</dfn> برای هم‌اندازه‌کردن دنباله‌ها، <dfn>Beginning of sequence یا bos (آغاز دنباله)</dfn> و <dfn>End of sequence یا eos (پایان دنباله)</dfn>. در نسخهٔ فعلی ما این سه نشانه پیاده نشده‌اند: پنجره‌ها هم‌اندازه‌اند و تولید با تعداد نشانهٔ درخواستی متوقف می‌شود.</p>
<p><dfn>Text normalization (یکسان‌سازی متن)</dfn> یعنی تبدیل شکل‌های انتخاب‌شده به یک قرارداد مشترک؛ مثلاً یکسان‌کردن «ي» عربی و «ی» فارسی. این کار با نرمال‌سازی عددی لایه‌ها فرق دارد و می‌تواند اطلاعات متن اصلی را تغییر دهد. نشانه‌بند ما خودکار چنین تبدیلی نمی‌دهد. نیم‌فاصله هم یک کاراکترِ مستقل است، نه فاصله‌ای که بی‌اجازه حذفش کنیم.</p>
<p><dfn>Corpus (پیکره)</dfn> مجموعهٔ متن‌های مورد استفاده است. پروژه آن را از فایل <dfn>UTF-8 (رمزگذاری متن یونیکد با دنبالهٔ بایت)</dfn> می‌خواند. یک کاراکترِ فارسی ممکن است چند بایت داشته باشد؛ شمار بایت فایل را با شمار کاراکترِ رشته یکی نگیرید.</p>
<p><code>CharacterTokenizer</code> کلاس نشانه‌بند کاراکترمحور پروژه است. متد <code>from_text</code> واژگان را از متن می‌سازد و ویژگی <code>id_to_token</code> همان فهرست مرتب نشانه‌هاست. متد <code>save</code> این فهرست را ذخیره می‌کند و <code>load</code> همان ترتیب را برمی‌گرداند و اعتبارش را می‌سنجد. مهم این است که پس از بارگذاری، هر نشانه همچنان همان شناسهٔ قبلی را داشته باشد. در آزمایش مرجع، <code>TemporaryDirectory</code> پوشه‌ای موقت می‌سازد که پس از پایان آزمایش پاک می‌شود؛ هیچ واژگان موجودی را بازنویسی نمی‌کنیم.</p>""",
"«می‌روم home» را رفت‌وبرگشت دهید. واژگان را در یک فایل تازه ذخیره و دوباره بارگذاری کنید. سپس «ژ» را وارد کنید و تفاوت خروجی را ثبت کنید. در پایان دو شناسهٔ معمولی واژگان را جابه‌جا کنید و اثر آن را پیش‌بینی کنید.",
"متن شناخته‌شده و نیم‌فاصله باید دقیق برگردند؛ ژ به صفر و سپس � می‌رسد. ترتیب واژگان پس از ذخیره/بارگذاری باید دقیقاً یکسان باشد. صرفاً یکسان‌بودن اندازهٔ دو واژگان برای سازگاری با وزن‌ها کافی نیست.",
"آیا نشانهٔ ناشناخته همان نشانهٔ پایان متن است؟ اگر دو کاراکتر به ناشناخته تبدیل شوند، آیا decode می‌تواند متن اصلی را حدس بزند؟",
"فایل ذخیرهٔ مدل نهایی، خودِ واژگان را نگه می‌دارد تا وزن‌ها با یک فایل واژگان اشتباه جفت نشوند. tokenizer.py اکنون نسخهٔ کامل همین قرارداد کوچک است.",
code="""from pathlib import Path
from tempfile import TemporaryDirectory
from mini_gpt.tokenizer import CharacterTokenizer

text = "می‌روم home"
tokenizer = CharacterTokenizer.from_text(text)
assert tokenizer.decode(tokenizer.encode(text)) == text
assert tokenizer.encode("ژ") == [0]
assert tokenizer.decode([0]) == "�"
with TemporaryDirectory() as directory:
    path = Path(directory) / "vocabulary.json"
    tokenizer.save(path)
    restored = CharacterTokenizer.load(path)
    assert restored.id_to_token == tokenizer.id_to_token
    assert restored.encode(text) == tokenizer.encode(text)
print(tokenizer.encode(text), tokenizer.decode(tokenizer.encode("ژ")))
""", source="mini_gpt/tokenizer.py"),

Lesson("22-bpe", 4, "متن قابل اعتماد", "چرا زیرواژه بین کاراکتر و کلمه قرار می‌گیرد؟",
"یک جفت پرتکرار را ادغام کنیم و قواعد آموخته‌شده را روی واژهٔ تازه دوباره اجرا کنیم.",
"""<p>نشانه‌بند کاراکترمحور یک مزیت روشن دارد: با واژگان نسبتاً کوچک کار می‌کند. در عوض، متن را به دنبالهٔ بلندی از نشانه‌ها تبدیل می‌کند. اگر متن را با فاصله به کلمه‌ها تقسیم کنیم، دنباله کوتاه‌تر می‌شود، اما باید برای واژه‌های تازه و نشانه‌گذاری تصمیم بگیریم. <dfn>Subword (زیرواژه)</dfn> قطعه‌ای میان این دو انتخاب است؛ یک قطعه ممکن است واژهٔ کامل باشد و قطعه‌ای دیگر فقط بخش پرتکرارش.</p>
<p><dfn>Byte Pair Encoding یا BPE (نشانه‌بندی با ادغام جفت‌های پرتکرار)</dfn> از واحدهای کوچک آغاز می‌کند، جفت‌های مجاور را می‌شمارد و یک جفت پرتکرار را به واحدی تازه تبدیل می‌کند. سپس دوباره می‌شمارد؛ شمارشِ دور قبل برای همهٔ دورها کافی نیست. نام این روش از فشرده‌سازی بایت‌ها آمده، اما مثال این درس عمداً از کاراکتر آغاز می‌شود.</p>
<p>در «کار» با فراوانی ۲ و «کارگر» با فراوانی ۱، جفت‌های ک،ا و ا،ر هرکدام سه بار دیده می‌شوند. اگر ک،ا را نخست انتخاب کنیم، «کار» به [کا،ر] و «کارگر» به [کا،ر،گ،ر] تبدیل می‌شود. با یک ادغام دیگر، قطعهٔ «کار» ساخته می‌شود. برای تساوی‌ها باید قانون ثابت داشته باشیم؛ کد مرجع ترتیب رشته‌ای Python را به کار می‌برد و ممکن است ابتدا ا،ر را برگزیند.</p>
<p>ادغام باید از چپ به راست و بدون هم‌پوشانی انجام شود. برای «aaaa»، ادغام a،a خروجی [aa،aa] می‌دهد، نه سه قطعهٔ aa. هنگام <em>آموزش</em> جفت‌ها را از پیکره انتخاب می‌کنیم؛ هنگام <em>کدگذاری متن تازه</em> همان قواعد ذخیره‌شده را به همان ترتیب اجرا می‌کنیم. دوباره انتخاب‌کردن پرتکرارترین جفتِ متن تازه، قرارداد دیگری است.</p>
<p>کد این درس برای هر واژه جدا کار می‌کند و فقط ساخت و اجرای قواعد ادغام را نشان می‌دهد؛ هنوز واژگان شناسه‌دار، فاصله‌ها، نشانه‌های ویژه و همهٔ موارد ناشناخته را مدیریت نمی‌کند. در <dfn>Byte-level tokenization (نشانه‌بندی با پایهٔ بایت)</dfn>، واحد آغازین بایت‌های متن است، نه کاراکترهای Python؛ این انتخاب می‌تواند پوشش متن‌های تازه را بهتر کند ولی نمایش قطعه‌ها پیچیده‌تر می‌شود.</p>
<p>واژگان بزرگ‌تر اغلب دنباله را کوتاه‌تر می‌کند، اما جدول ورودی و خروجی مدل را هم بزرگ‌تر می‌کند. پس نمی‌توانیم فقط با شمردن نشانه‌ها انتخاب کنیم. در این کتاب می‌خواهیم اثر تغییر معماری را مقایسه کنیم؛ به همین دلیل، نشانه‌بند Mini-GPT را کاراکترمحور نگه می‌داریم. اگر هم‌زمان نشانه‌بند را هم عوض کنیم، جداکردن اثر این دو تغییر دشوار می‌شود.</p>""",
"تابع ادغام غیرهم‌پوشان را خودتان بنویسید. دو قاعده از «کار/کارگر» و جداگانه از «low/lower» بیاموزید؛ قواعد را روی «کارگاه» و «lowest» اجرا کنید. ثابت کنید از متن تازه برای انتخاب قاعده استفاده نکرده‌اید.",
"کد مرجع در هر دور شمارش را از وضعیت تازه می‌سازد و تساوی را قطعی حل می‌کند. پس از دو ادغام، قطعهٔ کار و قطعهٔ low ساخته می‌شوند. پیوستن قطعه‌های متن تازه باید همان متن را بازگرداند؛ این آزمون برای این نسخهٔ صرفاً کاراکترمحور و بدون تغییر متن معتبر است.",
"چرا فهرست قطعه‌ها به‌تنهایی برای بازسازی همین الگوریتم کدگذاری کافی نیست و ترتیب قواعد ادغام هم لازم است؟",
"قواعد BPE را در همین آزمایش مستقل نگه دارید. نسخهٔ اصلی Mini-GPT همچنان کاراکترمحور است؛ وقتی معماری را تغییر می‌دهیم، می‌خواهیم بدانیم تغییر نتیجه از کدام بخش آمده است.",
code="""from collections import Counter

def merge(tokens, pair):
    output = []
    index = 0
    while index < len(tokens):
        if index+1 < len(tokens) and (tokens[index], tokens[index+1]) == pair:
            output.append(tokens[index] + tokens[index+1])
            index += 2
        else:
            output.append(tokens[index])
            index += 1
    return output

def learn_rules(words, number):
    corpus = [(list(word), frequency) for word, frequency in words]
    rules = []
    for _ in range(number):
        counts = Counter()
        for tokens, frequency in corpus:
            for pair in zip(tokens, tokens[1:]):
                counts[pair] += frequency
        if not counts:
            break
        pair = min(counts, key=lambda candidate: (-counts[candidate], candidate))
        rules.append(pair)
        corpus = [(merge(tokens, pair), frequency) for tokens, frequency in corpus]
    return rules

def encode_with_rules(word, rules):
    tokens = list(word)
    for pair in rules:
        tokens = merge(tokens, pair)
    return tokens

assert merge(list("aaaa"), ("a", "a")) == ["aa", "aa"]
examples = [
    ([("کار", 2), ("کارگر", 1)], "کارگاه"),
    ([("low", 2), ("lower", 1)], "lowest"),
]
for training_words, fresh_word in examples:
    rules = learn_rules(training_words, number=2)
    tokens = encode_with_rules(fresh_word, rules)
    assert "".join(tokens) == fresh_word
    assert len(tokens) < len(fresh_word)
    print("rules:", rules, "new word:", fresh_word, "pieces:", tokens)
"""),

Lesson("23-shift", 4, "نمونهٔ آموزش", "چرا هدف دقیقاً یک خانه جلوتر است؟",
"از یک دنباله، ورودی و هدف بسازیم و پیش از آموزش مطمئن شویم مدل مسئلهٔ درست را می‌بیند.",
"""<p>دنبالهٔ [A,B,C,D,E] را داریم. <dfn>Context length (طول زمینه)</dfn> تعداد نشانه‌های ورودی یک پنجره است و در کد با context_length مشخص می‌شود. اگر T=4 باشد، ورودی [A,B,C,D] و هدف [B,C,D,E] است. در موقعیت نخست، مدل پس از دیدن A باید B را حدس بزند؛ در موقعیت سوم، پس از A,B,C باید D را پیش‌بینی کند. یک پنجره چهار هدف دارد، نه فقط یک هدف در انتها.</p>
<div class="math">x[t] = tokens[start+t]<br>y[t] = tokens[start+t+1] ; 0≤t&lt;T</div>
<p>start ابتدای پنجره و t موقعیت درون آن است. برای T ورودی، T+1 شناسهٔ خام لازم داریم تا هدفِ آخر هم وجود داشته باشد. از N شناسه، با حرکت یک‌خانه‌ای پنجره، N−T نمونه می‌سازیم. شکل هر x و y برابر (T,) و شکل دستهٔ آن‌ها (B,T) است.</p>
<p><dfn>Sliding window (پنجرهٔ لغزان)</dfn> یعنی یک برش هم‌طول را با شروع‌های مختلف برداریم. پنجره‌های مجاور بیشتر متنشان مشترک است؛ نباید آن‌ها را نمونه‌های کاملاً مستقل آماری فرض کرد. اعتبارسنجی فعلی پروژه میانگین زیان هدف‌های همین پنجره‌هاست، نه سنجش هر کاراکترِ پیکره دقیقاً یک‌بار.</p>
<p>یک خطر مهم باقی است: هنگام محاسبهٔ هم‌زمانِ پنجره، هدفِ موقعیت نخست در ورودیِ موقعیت دوم حضور دارد. بعداً با محدودکردن جریان اطلاعات، جلوی دسترسی هر موقعیت به آینده را می‌گیریم. جابه‌جایی درست هدف لازم است، اما به‌تنهایی جلوگیری از نشت آینده نیست.</p>
<p>اگر y=x بگذاریم، مسئله از «بعدش چه می‌آید؟» به «همین را کپی کن» تغییر می‌کند. اگر هدف را دو خانه جلو ببریم، مسئلهٔ دیگری ساخته‌ایم. کاهش زیانِ یک مسئلهٔ اشتباه، پیروزی نیست؛ فقط برنامه با دقت بیشتری کار اشتباه را انجام می‌دهد.</p>""",
"برای [1,2,3,4,5] و T=3، همهٔ جفت‌های x/y را روی کاغذ بنویسید. سپس اولین و آخرین نمونهٔ متن فارسی خود را بازگردانی کنید و هر خانهٔ هدف را با کاراکترِ بعدی ورودی تطبیق دهید.",
"دو نمونه داریم: [1,2,3]→[2,3,4] و [2,3,4]→[3,4,5]. شاخص ۲ بیرون محدوده است. در هر دو، y[:-1] با x[1:] برابر است؛ هدف آخر را باید از شناسهٔ خام بعد از آخرین ورودی گرفت.",
"چرا هدفِ درستِ جابه‌جاشدهٔ یک‌خانه‌ای، هنوز به‌تنهایی ثابت نمی‌کند مدل آینده را نمی‌بیند؟",
"NextTokenDataset دقیقاً همین برش‌ها را می‌سازد. آموزش و اعتبارسنجی Dataset جدا دارند تا هیچ پنجره‌ای از مرز میان آن‌ها عبور نکند.",
code="""import torch
from mini_gpt.dataset import NextTokenDataset

dataset = NextTokenDataset([1, 2, 3, 4, 5], context_length=3)
assert len(dataset) == 2
for x, y in dataset:
    assert torch.equal(x[1:], y[:-1])
    print(x.tolist(), y.tolist())
assert dataset[0][1][-1].item() == 4
assert dataset[1][1][-1].item() == 5
""", source="mini_gpt/dataset.py"),

Lesson("24-data-contract", 4, "نمونهٔ آموزش", "چه چیزهایی پیش از آموزش باید دربارهٔ داده بدانیم؟",
"پیش از خرج‌کردن زمان آموزش، طول، مرز، واژگان و هویت متن را وارسی کنیم.",
"""<p>پیش از شروع آموزش، ببینید اصلاً می‌توان از هر دو بخش داده پنجره ساخت یا نه. هرکدام باید بیش از T شناسه داشته باشند تا یک پنجرهٔ ورودی/هدف بسازند. البته طول کافی به‌تنهایی چیزی دربارهٔ کیفیت متن نمی‌گوید. فایل نمونهٔ پروژه کوتاه و برای تمرین است؛ از آموزش روی آن انتظار تولید متن روان نداشته باشید.</p>
<p>در این آزمایش، واژگان فقط از بخش آموزش ساخته می‌شود. کاراکترِ تازهٔ اعتبارسنجی به شناسهٔ ناشناخته می‌رود. <dfn>Unknown rate (نرخ ناشناخته)</dfn> نسبت شمار این شناسه‌ها به کل شناسه‌های اعتبارسنجی است. مقدار زیاد ممکن است از تفاوت منبع، نگارش یا پاک‌سازی بیاید؛ پیش از تفسیر زیان، ببینید مدل واقعاً چه متنی را به‌صورت ورودی دریافت کرده است.</p>
<p>این قاعده برای ساخت نشانه‌بندِ همین آزمایش از همین پیکره است. استفاده از یک نشانه‌بند ازپیش‌آموخته و ثابت، لزوماً نشت داده نیست؛ باید منشأ آن و قرارداد ارزیابی روشن باشد. مسئله، استفادهٔ پنهان از اطلاعاتی است که در آزمایش مدعی ندیدنشان هستیم.</p>
<p>برای ادامهٔ آموزش، لازم است بدانیم همان محتوا را دوباره خوانده‌ایم. <dfn>Hash (اثر انگشت محتوا)</dfn> خلاصه‌ای با طول ثابت از داده می‌سازد. پروژه از <dfn>SHA-256 (تابع اثر انگشت ۲۵۶بیتی)</dfn> استفاده می‌کند؛ تغییر محتوا با احتمال خطای بسیار ناچیز مقدار ثبت‌شده را عوض می‌کند. این معیار کیفیت یا اصالت علمی متن نیست، فقط بررسی هویت محتواست.</p>
<p>تابع <code>prepare_corpus</code> این آماده‌سازی را انجام می‌دهد: متن را می‌خواند، به دو برش پیوسته تقسیم می‌کند، واژگان را از آموزش می‌سازد و چهار چیز برمی‌گرداند: شناسه‌های آموزش، شناسه‌های اعتبارسنجی، نشانه‌بند و اطلاعات ثبت‌شده. به این جداسازی «برش پیوسته» می‌گوییم، نه «تقسیم زمانی»؛ ترتیب متن در فایل الزاماً ترتیب رخدادها در زمان نیست.</p>
<p>اگر چند سند دارید، فقط به محل برش نگاه نکنید؛ سندهای کامل را جدا کنید و تکرارها را بسنجید. چسباندن دو سند هم می‌تواند یک گذار مصنوعی بسازد: مدل ادامهٔ پایان یک سند را در ابتدای سند بعدی می‌بیند. اگر نشانهٔ جداکننده اضافه کردید، باید معنای آن در داده، واژگان و تولید ثابت بماند. این تصمیم‌ها مستقیماً تعیین می‌کنند مدل چه چیزی یاد می‌گیرد؛ بخشی از طراحی آزمایش‌اند.</p>""",
"prepare_corpus را اجرا و طول دو بخش، اندازهٔ واژگان و نرخ ناشناخته را ثبت کنید. سپس آخرین ده کاراکترِ آموزش و نخستین ده کاراکترِ اعتبارسنجی را ببینید. آیا بریدن متن در همین نقطه برای ادعای آزمایش شما مناسب است؟",
"عددها به فایل بستگی دارند. معیار عبور: طول کافی برای هر دو بخش، توضیح کاراکترهای ناشناخته و آگاهی از مرز متن. تغییر هر بخش از محتوای خوانده‌شده باید اثر انگشت ذخیره‌شده را تغییر دهد.",
"اگر نرخ ناشناخته زیاد باشد، چرا مقایسهٔ مستقیم زیان دو نشانه‌بند می‌تواند گمراه‌کننده باشد؟",
"فرمان آموزش همین اطلاعات را گزارش می‌کند و همراه وضعیت ذخیره‌شده نگه می‌دارد. در [[journal.html|دفتر آزمایش]]، منبع داده و علت انتخاب مرز را هم ثبت کنید؛ اثر انگشت جای توضیح علمی را نمی‌گیرد.",
code="""from pathlib import Path
from mini_gpt.data import prepare_corpus

path = "data/sample.txt"
train_ids, valid_ids, tokenizer, info = prepare_corpus(path)
text = Path(path).read_text(encoding="utf-8")
boundary = info["train_characters"]
assert len(train_ids) == boundary
assert len(valid_ids) == len(text)-boundary
assert 0 <= info["validation_unknown_rate"] <= 1
print("lengths and vocabulary:", len(train_ids), len(valid_ids), tokenizer.vocab_size)
print("boundary:", repr(text[max(0, boundary-10):boundary]), repr(text[boundary:boundary+10]))
print(info)
""", source="mini_gpt/data.py"),

Lesson("25-embedding", 4, "نمایش یادگرفتنی", "یک شناسه چطور به بردار قابل آموزش تبدیل می‌شود؟",
"شمارهٔ نشانه را نشانیِ یک سطر بدانیم و ببینیم تکرار یک نشانه چگونه گرادیان را جمع می‌کند.",
"""<p>شبکهٔ کوچکی که ساختیم، چند ویژگی عددی می‌گرفت. متن فعلی ما فقط شناسه دارد. اگر شناسهٔ ۴ را مانند یک اندازهٔ عددی به شبکه بدهیم، رابطه‌ای وارد محاسبه کرده‌ایم که در واژگان وجود ندارد: نشانهٔ ۴ دو برابر نشانهٔ ۲ نیست. می‌خواهیم شناسه فقط نشانی باشد و عددهای قابل آموزش را از جای دیگری برداریم.</p>
<p>یک جدول کوچک مانند <code>E=[[1,0],[0,2],[3,4]]</code> این جداسازی را انجام می‌دهد. شناسهٔ ۲ سطر <code>[3,4]</code> را انتخاب می‌کند؛ حالا برای آن نشانه دو ویژگی عددی داریم. <dfn>Embedding (نمایش برداری یادگرفتنی)</dfn> هر نشانه را به چنین مجموعه‌ای از عددهای قابل آموزش وصل می‌کند. در حالت کلی، جدول E با V سطر و C ستون داریم: یک سطر برای هر نشانه و C ویژگی برای نمایش آن.</p>
<div class="math">E: (V,C)<br>ids(B,T) → E[ids]: (B,T,C)</div>
<p><dfn>Lookup (برداشتن مقدار از جدول با شناسه)</dfn> دقیقاً کار این مرحله است. <code>nn.Embedding(V,C)</code> جدول پارامتری را می‌سازد و فراخوانی آن با شناسه‌ها، سطرهای مربوط را برمی‌دارد. تفاوت با دیکشنری ثابت این است که عددهای سطرها از طریق زیان آموزش تغییر می‌کنند.</p>
<p><dfn>One-hot (برداری با یک مؤلفهٔ یک و بقیهٔ مؤلفه‌ها صفر)</dfn> برای شناسهٔ ۲ در واژگان چهارعضوی [0,0,1,0] است. ضرب این بردار در جدول E همان سطر ۲ را برمی‌دارد. پیاده‌سازی جدول، ما را از ساختن آن همه صفر بی‌نیاز می‌کند. شناسهٔ یکسان در دو موقعیت، در این مرحله بردار یکسان می‌دهد.</p>
<p>برای همان جدول سه‌سطرهٔ آغاز درس، Vector انتخاب‌گر <code>[0,0,1]</code> نیز در ضرب ماتریسی سطر <code>[3,4]</code> را می‌دهد: صفر برابر سطر اول، صفر برابر سطر دوم و یک برابر سطر سوم. Lookup همان سطر را بدون ساختن این Vector پر از صفر برمی‌دارد. در آموزش، خودِ شناسه یا عمل انتخاب تغییر نمی‌کند؛ عددهای جدول E هستند که Gradient آن‌ها را تغییر می‌دهد.</p>
<p>مقدارهای آغازین تصادفی‌اند و دامنهٔ آن‌ها به روش مقداردهی اولیه بستگی دارد؛ جدول تازه هنوز معنای زبانی یاد نگرفته است. در مدل نهایی، روش آغاز را صریح کنترل می‌کنیم. بعد از آموزش نیز نمی‌توان تضمین کرد هر ستون نام انسانی روشنی مانند «زمان» یا «جنسیت» داشته باشد.</p>
<p>اگر شناسهٔ ۱ دو بار استفاده شود، گرادیان هر دو مسیر در همان سطر جمع می‌شود. در زیان ساختگیِ «جمع همهٔ نمایش‌ها»، هر مؤلفهٔ سطر ۱ گرادیان ۲ و هر مؤلفهٔ سطرِ یک‌باراستفاده‌شده گرادیان ۱ می‌گیرد. زیان واقعی مقدارهای دیگری می‌سازد، اما قاعدهٔ جمع سهم مسیرها همان است.</p>
<p>با همهٔ این تغییرها، جدول هنوز یک محدودیت دارد: یک شناسه را هر جای متن ببریم، همان سطر را می‌گیریم. <dfn>Contextual representation (نمایش وابسته به زمینه)</dfn> وقتی ساخته می‌شود که نمایش یک Token در یک موقعیت مشخص، اطلاعات موقعیت‌های دیگر را هم بگیرد. جدول اولیه هنوز این کار را نمی‌کند؛ برای آن باید راهی بسازیم که اطلاعات میان موقعیت‌ها منتقل شود. سازوکار توجه همین‌جا به کارمان خواهد آمد.</p>""",
"انتخاب سطر را ابتدا با <code>embedding.weight[ids]</code> انجام دهید و با nn.Embedding مقایسه کنید. برای [1,3,1] مجموع نمایش‌ها را مشتق بگیرید؛ قبل از اجرا گرادیان هر پنج سطر را بنویسید.",
"شکل نمایش (1,3,3) است. گرادیان سطر ۱ سه عدد ۲، سطر ۳ سه عدد ۱ و بقیه صفر است. در این مثال فقط جدول ورودی استفاده شده؛ اشتراک جدول با بخش‌های دیگر مدل می‌تواند مسیرهای گرادیان دیگری اضافه کند.",
"اگر شناسه‌های دو نشانه را جابه‌جا کنیم ولی سطرهای جدول را ثابت بگذاریم، مدل چه قرارداد نادرستی را دریافت می‌کند؟",
"نسخهٔ v1 پس از جدول نمایش، یک لایهٔ خطی به اندازهٔ واژگان دارد تا امتیاز نشانهٔ بعدی را بسازد. هنوز نمایش هر موقعیت، نشانه‌های قبلی را ترکیب نمی‌کند؛ این نسخه، حد پایهٔ عصبی ماست.",
code="""import torch
from torch import nn
from mini_gpt.stages.v1 import TokenOnly

embedding = nn.Embedding(5, 3)
ids = torch.tensor([[1, 3, 1]], dtype=torch.long)
x = embedding(ids)
assert torch.equal(x, embedding.weight[ids])
x.sum().backward()
expected = torch.tensor([[0., 0., 0.], [2., 2., 2.], [0., 0., 0.],
                         [1., 1., 1.], [0., 0., 0.]])
assert torch.equal(embedding.weight.grad, expected)
model = TokenOnly(vocab_size=5, channels=3)
assert tuple(model(ids).shape) == (1, 3, 5)
print(x.shape, embedding.weight.grad, sep="\\n")
""", source="mini_gpt/stages/v1.py"),

Lesson("26-positions", 4, "نمایش یادگرفتنی", "چرا جای نشانه را هم نمایش می‌دهیم؟",
"به نمایش هر نشانه، نشانیِ موقعیتش را اضافه کنیم و شکل خروجی را ثابت نگه داریم.",
"""<p>«سارا علی را دید» و «علی سارا را دید» واژه‌های یکسان اما ترتیب متفاوت دارند. در نسخهٔ کاراکترمحور ما، مثلاً هر وقوع «ا» از یک سطر جدول نشانه استفاده می‌کند؛ از خودِ آن سطر نمی‌توان فهمید این کاراکتر کجای جمله بوده است. پس یک منبع اطلاعات دیگر اضافه می‌کنیم: جایگاه.</p>
<p><dfn>Positional embedding (نمایش برداری موقعیت)</dfn> جدولی قابل آموزش است که برای موقعیت‌های ۰، ۱، ۲ و ... بردار دارد. Positional Embedding را با Token Embedding جمع می‌کنیم. این جمع، C ویژگی تازه به خروجی نمی‌چسباند؛ دو بردار Cتایی را به یک بردار Cتایی تبدیل می‌کند.</p>
<div class="math">x[b,t,:] = E_token[ids[b,t],:] + E_position[t,:]<br>E_position: (T_max,C)<br>(B,T,C) + (T,C) → (B,T,C)</div>
<p>b شمارهٔ نمونه، t جای نشانه و : همهٔ ویژگی‌ها را انتخاب می‌کند. T_max بیشترین تعداد موقعیتِ تعریف‌شده در جدول است. بردارهای موقعیت شکل (T,C) دارند و روی محور B گسترش می‌یابند؛ موقعیت صفرِ همهٔ نمونه‌ها از یک سطر جدول استفاده می‌کند.</p>
<p>این مرحله فقط اطلاعات جایگاه را به نمایش می‌افزاید؛ هنوز اطلاعات دو نشانه را با هم ترکیب نمی‌کند. حالا باید راهی بسازیم تا نمایش هر موقعیت از گذشته هم اطلاعات بگیرد. ابتدا چند راه ساده‌تر را مقایسه می‌کنیم و سپس Attention را قدم‌به‌قدم می‌سازیم. فعلاً مشاهدهٔ اختلاف دو بردار کافی است؛ اختلاف تصادفی را با یادگیری معنای ترتیب اشتباه نگیرید.</p>
<p>جدول آموختنی تعداد سطر محدودی دارد. اگر T از T_max بزرگ‌تر باشد، نشانیِ موقعیت‌های اضافه تعریف نشده است. در تولید متنِ بلندِ پروژه، آخرین T_max نشانه را نگه می‌داریم و جایگاه‌های همان پنجره را از صفر می‌شماریم. این تصمیم ساده محدودیت دارد و بعداً هنگام بحث حافظهٔ تولید دوباره بررسی‌اش می‌کنیم.</p>
<p>یک پرسش را برای بعد نگه دارید: آیا حذف جدول موقعیت، همهٔ اطلاعات ترتیب را نابود می‌کند؟ پاسخ به بقیهٔ معماری هم وابسته است. پس از یادگرفتن محدودیتِ دسترسی به آینده، این آزمایش را دقیق‌تر تفسیر خواهیم کرد.</p>""",
"دو وقوع یک شناسه را در موقعیت ۰ و ۲ بگذارید. برابری نمایش اولیه و تفاوت پس از افزودن موقعیت را پیش‌بینی کنید. سپس بررسی کنید خروجی هنوز (B,T,C) است.",
"دو نمایش اولیه دقیقاً برابرند چون یک سطر را برداشته‌اند. پس از جمع موقعیت، با مقداردهی تصادفیِ مرجع متفاوت‌اند. هیچ‌کدام هنوز آموزش ندیده‌اند؛ این فقط شاهد ورود اطلاعات متفاوت به دو جایگاه است.",
"اگر به‌جای جمع، دو بردار را کنار هم می‌چسباندیم، اندازهٔ ویژگی چه می‌شد و لایهٔ بعد باید چه تغییری می‌کرد؟",
"این جزء را اکنون مستقل ساختیم. نسخهٔ v4 پروژه آن را همراه توجه چندسر به مدل متصل می‌کند؛ آزمایش حذف موقعیت را پس از آشنایی با آن اجزا اجرا خواهیم کرد.",
code="""import torch
from torch import nn

torch.manual_seed(2)
ids = torch.tensor([[1, 2, 1]], dtype=torch.long)
token = nn.Embedding(5, 4)
position = nn.Embedding(8, 4)
base = token(ids)
positions = torch.arange(ids.shape[1])
x = base + position(positions)
assert torch.equal(base[0, 0], base[0, 2])
assert not torch.equal(x[0, 0], x[0, 2])
assert tuple(x.shape) == (1, 3, 4)
print(x.shape, "same token, different positions:", x[0, 0], x[0, 2])
""",
review="در پایان این بخش باید بتوانید متن را به شناسه، شناسه را به بردار و پنجره را به ورودی/هدف تبدیل کنید. اکنون وقت پرسش تازه است: هر موقعیت اطلاعات کدام موقعیت‌های دیگر را بگیرد؟"),
]
